rcore 1;
package `library` version "1";
metamodel "urn:intersect:example:library:1" prefix `lib` {
  class `Library` extends external "file:///definitions/common.ecore.rcore#//@eClassifiers.0" {
    ref `copies`: external "#//@eClassifiers.1" [0,*] containment opposite external "#//@eClassifiers.1/@eStructuralFeatures.2";
    ref `members`: external "#//@eClassifiers.2" [0,*] containment;
    ref `loans`: external "#//@eClassifiers.3" [0,*] containment;
    attr `copyCount`: EInt [0,1] derived;
  }
  class `BookCopy` extends external "file:///definitions/common.ecore.rcore#//@eClassifiers.0" {
    attr `title`: EString [0,1];
    attr `edition`: EInt [0,1] default "1";
    ref `library`: external "#//@eClassifiers.0" [0,1] opposite external "#//@eClassifiers.0/@eStructuralFeatures.0";
    attr `available`: EBoolean [0,1] derived;
  }
  class `Member` extends external "file:///definitions/common.ecore.rcore#//@eClassifiers.0" {
  }
  class `Loan` extends external "file:///definitions/common.ecore.rcore#//@eClassifiers.0" {
    ref `copy`: external "#//@eClassifiers.1" [1,1];
    ref `member`: external "#//@eClassifiers.2" [1,1];
  }
}

rcore 1;
package `common` version "1";
metamodel "urn:intersect:example:common:1" prefix `common` {
  abstract class `Named` {
    attr `name`: EString [1,1];
  }
}

grammar example.Library with org.eclipse.xtext.common.Terminals
import "urn:intersect:example:library:1" as lib

Library returns lib::Library:
  'library' name=ID '{'
    (copies+=BookCopy | members+=Member | loans+=Loan)*
  '}';

BookCopy returns lib::BookCopy:
  'copy' name=ID title=STRING ('edition' edition=INT)? ';';

Member returns lib::Member:
  'member' name=ID ';';

Loan returns lib::Loan:
  'loan' name=ID 'copy' copy=[lib::BookCopy|ID]
  'to' member=[lib::Member|ID] ';';

rcore 1;
package fixtureProviders version "1";
import model "urn:intersect:example:library:1" as m;
derive m.`Library`.`copyCount` using count(`copies`);
derive m.`BookCopy`.`available` using noIncoming(m.`Loan`.`copy`);
validate m.`Loan`.rule0(self) {
  require size(incoming::<m.`Loan`>(self.`copy`, "copy")) <= 1
    code "rule0" message "A book copy cannot have more than one active loan.";
}
